#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::{HashMap, HashSet};

    #[test]
    fn ids_are_unique() {
        let mut seen = HashSet::new();
        for rule in CATALOG {
            assert!(seen.insert(rule.id), "duplicate scanner id: {}", rule.id);
        }
    }

    #[test]
    fn every_rule_has_at_least_one_path_and_platform() {
        for rule in CATALOG {
            assert!(!rule.paths.is_empty(), "{} has no paths", rule.id);
            assert!(!rule.platforms.is_empty(), "{} has no platforms", rule.id);
        }
    }

    #[test]
    fn every_rule_explains_itself_in_plain_language() {
        for rule in CATALOG {
            assert!(!rule.name.is_empty(), "{} has no name", rule.id);
            assert!(
                rule.explanation.len() > 40,
                "{} needs a real explanation, not a label",
                rule.id
            );
            assert!(
                !rule.explanation.contains("DerivedData") || rule.explanation.contains("Xcode"),
                "{} uses jargon without explaining it",
                rule.id
            );
        }
    }

    #[test]
    fn confidence_is_a_probability() {
        for rule in CATALOG {
            assert!(
                (0.0..=1.0).contains(&rule.confidence),
                "{} has an out-of-range confidence",
                rule.id
            );
        }
    }

    #[test]
    fn no_rule_targets_a_bare_home_or_root() {
        for rule in CATALOG {
            for path in rule.paths {
                assert!(
                    *path != "~" && *path != "~/" && *path != "/",
                    "{} targets the whole home directory",
                    rule.id
                );
            }
        }
    }

    #[test]
    fn no_rule_uses_parent_directory_traversal() {
        for rule in CATALOG {
            for path in rule.paths {
                assert!(!path.contains(".."), "{} uses `..` in a path", rule.id);
            }
        }
    }

    #[test]
    fn nothing_that_needs_re_downloading_is_marked_safe() {
        // Models and simulator images are always Review: they cost the user a
        // large download or lose state, so they never get one-click deletion.
        for rule in CATALOG {
            if matches!(rule.category, Category::AiModel | Category::DeviceImage) {
                assert_eq!(
                    rule.risk,
                    RiskLevel::Review,
                    "{} must not be one-click deletable",
                    rule.id
                );
            }
        }
    }

    /// Literal (non-wildcard) paths a rule claims, with a `*` prefix kept as
    /// the parent so overlap can be reasoned about.
    fn literal_paths(rule: &PathRule) -> Vec<&'static str> {
        rule.paths.iter().copied().filter(|p| !p.contains('*')).collect()
    }

    #[test]
    fn no_two_rules_claim_exactly_the_same_path() {
        let mut seen: HashMap<&str, &str> = HashMap::new();
        for rule in CATALOG {
            for path in literal_paths(rule) {
                if let Some(other) = seen.insert(path, rule.id) {
                    panic!("{} and {} both claim {path}", other, rule.id);
                }
            }
        }
    }

    #[test]
    fn a_wildcard_sweep_cedes_every_folder_a_named_rule_owns() {
        // Without this, the broad sweep and the specific scanner both report
        // the same bytes. The engine collapses that safely, but the user ends
        // up reading the vaguer of the two explanations — so the sweep has to
        // name what it is giving up.
        for sweep in CATALOG {
            for pattern in sweep.paths.iter().filter(|p| p.ends_with("/*")) {
                let parent = pattern.trim_end_matches("/*");

                for other in CATALOG.iter().filter(|r| r.id != sweep.id) {
                    for path in literal_paths(other) {
                        let Some(rest) = path.strip_prefix(parent).and_then(|r| r.strip_prefix('/'))
                        else {
                            continue;
                        };
                        let owned = rest.split('/').next().unwrap_or(rest);
                        assert!(
                            sweep.exclude.iter().any(|e| e.eq_ignore_ascii_case(owned)),
                            "{} sweeps {parent}/* but does not exclude `{owned}`, which {} owns",
                            sweep.id,
                            other.id,
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn no_rule_is_nested_inside_another_rules_literal_path() {
        // A rule reporting a folder inside another rule's folder is double
        // counted until the engine merges it, and the merge always keeps the
        // outer one — so the inner rule would silently never be seen.
        for rule in CATALOG {
            for path in literal_paths(rule) {
                for other in CATALOG.iter().filter(|r| r.id != rule.id) {
                    for other_path in literal_paths(other) {
                        assert!(
                            !(path.starts_with(other_path)
                                && path.len() > other_path.len()
                                && path.as_bytes()[other_path.len()] == b'/'),
                            "{} claims {path}, which is inside {}'s {other_path}",
                            rule.id,
                            other.id,
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn platform_lists_contain_only_known_platforms() {
        for rule in CATALOG {
            for platform in rule.platforms {
                assert!(
                    ["macos", "linux", "windows"].contains(platform),
                    "{} lists unknown platform {platform}",
                    rule.id
                );
            }
        }
    }

    #[test]
    fn the_catalog_covers_every_family() {
        let families: HashSet<_> = CATALOG.iter().map(|r| r.family).collect();
        assert!(families.contains(&Family::General));
        assert!(families.contains(&Family::Developer));
        assert!(families.contains(&Family::Browser));
        assert!(families.contains(&Family::Ai));
    }
}
